import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        v = []
        for _ in range(n):
            v.append(int(next(iterator)))
    except StopIteration:
        return

    # Create a sorted copy to compare against
    sorted_v = sorted(v)

    # Find the first index where v differs from sorted_v
    start = -1
    for i in range(n):
        if v[i] != sorted_v[i]:
            start = i
            break

    # If the array is already sorted
    if start == -1:
        print("1 1")
        return

