    end = -1
    for i in range(n - 1, -1, -1):
        if v[i] != sorted_v[i]:
            end = i
            break

    # Reverse the segment [start, end] in the original array
    # We do this by swapping elements from start to end towards the center
    left, right = start, end
    while left < right:
        v[left], v[right] = v[right], v[left]
        left += 1
        right -= 1

    # Check if the modified array is now sorted
    is_sorted = True
    for i in range(n):
        if v[i] != sorted_v[i]:
            is_sorted = False
            break

    if is_sorted:
        # Output 1-based indices
